-- =============================================================================================
-- Hand-written below this line: walk-in request rules, the extended online admission backstop,
-- row-level security and grants. See docs/architecture/DATA_MODEL.md section 5.
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- walk_in_requests
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "walk_in_requests" ADD CONSTRAINT "walk_in_requests_name_trimmed"
  CHECK ("visitor_name" = btrim("visitor_name") AND length("visitor_name") BETWEEN 1 AND 200);
ALTER TABLE "walk_in_requests" ADD CONSTRAINT "walk_in_requests_phone_e164"
  CHECK ("visitor_phone" IS NULL OR "visitor_phone" ~ '^\+[1-9][0-9]{6,14}$');
ALTER TABLE "walk_in_requests" ADD CONSTRAINT "walk_in_requests_plate_normalised"
  CHECK ("vehicle_plate" IS NULL OR "vehicle_plate" ~ '^[A-Z0-9-]{2,15}$');
ALTER TABLE "walk_in_requests" ADD CONSTRAINT "walk_in_requests_gate_trimmed"
  CHECK ("gate" IS NULL OR ("gate" = btrim("gate") AND length("gate") BETWEEN 1 AND 60));
-- A request is answered within minutes, not hours.
ALTER TABLE "walk_in_requests" ADD CONSTRAINT "walk_in_requests_expiry"
  CHECK ("expires_at" > "created_at" AND "expires_at" <= "created_at" + interval '30 minutes');
ALTER TABLE "walk_in_requests" ADD CONSTRAINT "walk_in_requests_decision_consistent"
  CHECK (("status" = 'PENDING') = ("decided_at" IS NULL)
         AND ("decided_at" IS NULL) = ("decided_by_user_id" IS NULL));

-- Decided once: only PENDING requests change, only their decision fields change, and a resident
-- cannot approve or deny after the request expired (the guard may still cancel it).
CREATE FUNCTION app_walk_in_request_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'walk-in request % is already decided', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."category", NEW."visitor_name",
      NEW."visitor_phone", NEW."vehicle_plate", NEW."gate", NEW."requested_by_user_id",
      NEW."expires_at", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."category", OLD."visitor_name",
      OLD."visitor_phone", OLD."vehicle_plate", OLD."gate", OLD."requested_by_user_id",
      OLD."expires_at", OLD."created_at") THEN
    RAISE EXCEPTION 'walk-in request % can only be decided', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" IN ('APPROVED', 'DENIED') AND now() > OLD."expires_at" THEN
    RAISE EXCEPTION 'walk-in request % has expired', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "walk_in_requests_guard"
  BEFORE UPDATE ON "walk_in_requests"
  FOR EACH ROW EXECUTE FUNCTION app_walk_in_request_guard();

-- ---------------------------------------------------------------------------------------------
-- visits: a walk-in approval is an alternative to an invitation, never both, and implies the
-- unit (so the composite key to the request's property and unit is checked).
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "visits" ADD CONSTRAINT "visits_walk_in_links_consistent"
  CHECK ("walk_in_request_id" IS NULL
         OR ("invitation_id" IS NULL AND "unit_id" IS NOT NULL));

-- Online admission backstop, extended (replaces the Part 1 version):
--   * every online admission is recorded now (within 5 minutes);
--   * with an invitation: active, inside its window, entries left, live pass (unchanged);
--   * to a unit without an invitation: an APPROVED walk-in request for that unit, admitted
--     within 15 minutes of the approval (each request admits once: unique walk_in_request_id).
CREATE OR REPLACE FUNCTION app_visit_admission_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  inv record;
  req record;
  used integer;
BEGIN
  IF NEW."source" <> 'ONLINE' OR NEW."decision" <> 'ADMITTED' THEN
    RETURN NEW;
  END IF;
  IF abs(extract(epoch FROM (NEW."arrived_at" - now()))) > 300 THEN
    RAISE EXCEPTION 'online admission must be recorded at the time it happens'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW."invitation_id" IS NOT NULL THEN
    SELECT "status", "valid_from", "valid_until", "max_entries" INTO inv
      FROM "visitor_invitations" WHERE "id" = NEW."invitation_id" FOR UPDATE;
    IF inv."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'visitor invitation % is revoked', NEW."invitation_id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."arrived_at" < inv."valid_from" OR NEW."arrived_at" > inv."valid_until" THEN
      RAISE EXCEPTION 'visitor invitation % is not valid at this time', NEW."invitation_id"
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT count(*) INTO used FROM "visits"
     WHERE "invitation_id" = NEW."invitation_id" AND "decision" = 'ADMITTED';
    IF used >= inv."max_entries" THEN
      RAISE EXCEPTION 'visitor invitation % has no entries left', NEW."invitation_id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."pass_id" IS NOT NULL AND EXISTS (
      SELECT 1 FROM "visitor_passes" WHERE "id" = NEW."pass_id" AND "revoked_at" IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'visitor pass % is revoked', NEW."pass_id"
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW."unit_id" IS NOT NULL THEN
    IF NEW."walk_in_request_id" IS NULL THEN
      RAISE EXCEPTION 'a visitor without a pass needs the resident''s approval to enter a unit'
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT "status", "decided_at" INTO req
      FROM "walk_in_requests" WHERE "id" = NEW."walk_in_request_id" FOR UPDATE;
    IF req."status" IS DISTINCT FROM 'APPROVED' THEN
      RAISE EXCEPTION 'walk-in request % is not approved', NEW."walk_in_request_id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."arrived_at" > req."decided_at" + interval '15 minutes' THEN
      RAISE EXCEPTION 'the approval of walk-in request % has lapsed', NEW."walk_in_request_id"
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

-- The visit guard (Part 1) gains the new column among the fields that never change.
CREATE OR REPLACE FUNCTION app_visit_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."departed_at" IS NOT NULL OR NEW."departed_at" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."invitation_id", NEW."pass_id",
         NEW."walk_in_request_id", NEW."category", NEW."visitor_name", NEW."visitor_phone",
         NEW."vehicle_plate", NEW."decision", NEW."denial_reason", NEW."gate", NEW."arrived_at",
         NEW."recorded_by_user_id", NEW."source", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."invitation_id", OLD."pass_id",
         OLD."walk_in_request_id", OLD."category", OLD."visitor_name", OLD."visitor_phone",
         OLD."vehicle_plate", OLD."decision", OLD."denial_reason", OLD."gate", OLD."arrived_at",
         OLD."recorded_by_user_id", OLD."source", OLD."created_at") THEN
    RAISE EXCEPTION 'visit % can only record its departure, once', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Row-level security and least privilege (no DELETE).
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "walk_in_requests" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "walk_in_requests" FORCE ROW LEVEL SECURITY;
CREATE POLICY "walk_in_requests_select" ON "walk_in_requests" FOR SELECT
  USING ("organisation_id" = app_current_organisation_id());
CREATE POLICY "walk_in_requests_insert" ON "walk_in_requests" FOR INSERT
  WITH CHECK ("organisation_id" = app_current_organisation_id());
CREATE POLICY "walk_in_requests_update" ON "walk_in_requests" FOR UPDATE
  USING ("organisation_id" = app_current_organisation_id())
  WITH CHECK ("organisation_id" = app_current_organisation_id());

REVOKE ALL ON "walk_in_requests" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "walk_in_requests" TO veyra_app;
